definition.frag:
// Duotone luminance map. Self-contained: no host helpers used.
vec4 srcPx = texture(u_tex, v_st);
float a = srcPx.a;
// Un-premultiply so luminance is measured on true color.
vec3 straight = a > 1e-5 ? srcPx.rgb / a : vec3(0.0);
float lum = dot(straight, vec3(0.2126, 0.7152, 0.0722));
lum = clamp(lum, 0.0, 1.0);
// Midpoint bias: remap so input 'midpoint' lands at 0.5.
float m = clamp(u_midpoint, 0.01, 0.99);
float t = pow(lum, log(0.5) / log(m));
// Contrast around 0.5.
t = clamp((t - 0.5) * u_contrast + 0.5, 0.0, 1.0);
vec3 duo = mix(u_shadowColor, u_highlightColor, t);
vec3 outRgb = mix(straight, duo, clamp(u_amount, 0.0, 1.0));
// Re-premultiply to preserve transparent edges.
o = vec4(outRgb * a, a);
